// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "Test", "TST"); }
    function testFuzz_property(address caller, uint256 burnAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner());
        vm.prank(c.owner());
        c.mintToken(caller, 1000);
        vm.assume(burnAmount > 0 && burnAmount <= 1000);
        uint256 supplyBefore = c.totalSupply();
        vm.prank(caller);
        bool ok;
        try c.burn(burnAmount) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 supplyAfter = c.totalSupply();
        bool invariant = (ok == false) && (supplyAfter == supplyBefore);
        assertTrue(invariant);
    }
}
